// 印章式标签：小圆角方块 + 单字（吉/凶/宜/忌），比胶囊更克制
function addSeal(parent, text, fg, bg, size) {
  const s = parent.addStack()
  s.layoutHorizontally()
  s.centerAlignContent()
  s.backgroundColor = bg
  s.cornerRadius = 4
  s.setPadding(1, 4, 1, 4)
  addText(s, text, { size: size || 9, weight: 'bold', color: fg, minScale: 0.6 })
  return s
}

